internal fun buildExtendedMaterialIcon(
    name: String,
    autoMirror: Boolean,
    vararg paths: Pair<String, PathFillType>,
): ImageVector {
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    )
    for ((d, fillType) in paths) {
        builder.addPath(
            pathData = addPathNodes(d),
            pathFillType = fillType,
            fill = SolidColor(Color.Black),
            fillAlpha = 1f,
            stroke = null,
            strokeAlpha = 1f,
            strokeLineWidth = 1f,
            strokeLineCap = StrokeCap.Butt,
            strokeLineJoin = StrokeJoin.Bevel,
            strokeLineMiter = 1f,
        )
    }
    return builder.build()
}

